use language::{Registry,Evidence,Definition};
use std::path::Path;
#[test]fn wave_is_first_class(){for name in ["hello.wave","hello.WAVE","a/b/conundrum.wave"]{let d=Registry::builtin().detect(Path::new(name),"");assert_eq!(d.name,"Wave");assert_eq!(d.evidence,Evidence::Extension);}}
#[test]fn filename_and_compound_suffix_precedence(){for(path,expected)in[("Cargo.lock","TOML"),("CMakeLists.txt","CMake"),("types.d.ts","TypeScript"),("Containerfile","Dockerfile")]{assert_eq!(Registry::builtin().detect(Path::new(path),"").name,expected);}assert!(!Registry::builtin().detect(Path::new("other.lock"),"").is_known());}
#[test]fn shebang_detection_does_not_reopen_files(){for text in ["#!/usr/bin/python3\n","#!/usr/bin/env -S python3 -u\n","\u{feff}#!/usr/bin/env DEBUG=1 python3.12\r\n"]{let d=Registry::builtin().detect(Path::new("/nonexistent/script"),text);assert_eq!(d.name,"Python");assert_eq!(d.evidence,Evidence::Shebang);}assert!(!Registry::builtin().detect(Path::new("script"),"#!/usr/bin/notpython3\n").is_known());}
#[test]fn incidental_content_does_not_override_known_extension(){assert_eq!(Registry::builtin().detect(Path::new("sample.rs"),"#!/bin/bash\n").name,"Rust");}
#[test]fn invalid_registration_is_atomic(){let mut r=Registry::from_json(r#"[{"id":"custom","name":"Custom","classifier":"plain","extensions":["custom"]}]"#).unwrap();assert_eq!(r.detect(Path::new("a.custom"),"").name,"Custom");let bad=Definition{id:"bad".into(),name:"Bad".into(),classifier:"plain".into(),extensions:vec!["new".into(),"custom".into()],filenames:vec![],interpreters:vec![]};assert!(r.register(bad).is_err());assert!(!r.detect(Path::new("a.new"),"").is_known());assert_eq!(r.definitions().count(),1);}
